import sys

def main():
    d = sys.stdin.read().split()
    n, m, k = int(d[0]), int(d[1]), int(d[2])
    w = [int(x) for x in d[3:3 + n]]
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    p = 3 + n
    for _ in range(m):
        a, b = find(int(d[p])), find(int(d[p + 1]))
        p += 2
        if a != b:
            parent[a] = b
    cost = {}
    size = {}
    for i in range(n):
        r = find(i)
        cost[r] = cost.get(r, 0) + w[i]
        size[r] = size.get(r, 0) + 1
    dp = [0] * (k + 1)
    for r in cost:
        c, v = cost[r], size[r]
        if c > k:
            continue
        for j in range(k, c - 1, -1):
            t = dp[j - c] + v
            if t > dp[j]:
                dp[j] = t
    print(dp[k])

main()

